-- V1.1 schema draft: adjust for actual auth/tenant framework; apply via migrations only
CREATE TABLE zones (id text PRIMARY KEY CHECK(id ~ '^Z0[1-9]$'), level_index int NOT NULL, position_index int NOT NULL, environment_cluster_id text, light_group_id text);
CREATE TABLE devices (id uuid PRIMARY KEY, zone_id text REFERENCES zones(id), installed_at timestamptz NOT NULL, removed_at timestamptz, device_token_hash text NOT NULL);
CREATE TABLE sensor_readings (id uuid PRIMARY KEY, device_id uuid NOT NULL REFERENCES devices(id), zone_id text NOT NULL REFERENCES zones(id), observed_at timestamptz NOT NULL, server_received_at timestamptz NOT NULL DEFAULT now(), metric text NOT NULL, value numeric, unit text NOT NULL, quality_flag text NOT NULL, calibration_ref text, idempotency_key text NOT NULL, raw_payload_hash text NOT NULL, UNIQUE(device_id,idempotency_key));
CREATE TABLE tasks (id uuid PRIMARY KEY, class_id uuid NOT NULL, matrix_code text NOT NULL CHECK(matrix_code ~ '^M(0[1-9]|1[0-9]|2[0-5])$'), prompt_version text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE response_versions (id uuid PRIMARY KEY, task_id uuid NOT NULL REFERENCES tasks(id), student_pseudonym text NOT NULL, phase text NOT NULL CHECK(phase IN ('pre_ai','revised','final')), version_no int NOT NULL, content jsonb NOT NULL, submitted_at timestamptz NOT NULL DEFAULT now(), UNIQUE(task_id,student_pseudonym,version_no));
CREATE TABLE consent_scopes (student_pseudonym text NOT NULL, scope text NOT NULL, permission boolean NOT NULL, consent_version text NOT NULL, approved_at timestamptz, PRIMARY KEY(student_pseudonym,scope));
-- production: use append-only grants/triggers, per-school authorization, audit log, export jobs and object storage schema; no direct role-grant implied by this DDL.
